{"file_path":"src/policies.js","content":"/**
 * Policy implementations: token buckets and sliding windows.
 *
 * Both keep one independent state per key, created the first time that key
 * reaches the policy. All tick arithmetic uses BigInt so arbitrarily large
 * ticks and counts stay exact.
 */

export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.capNum = capacity * per
    this.states = new Map()
  }

  #state(key) {
    let s = this.states.get(key)
    if (!s) {
      s = { tokensNum: this.capNum, lastTick: null }
      this.states.set(key, s)
    }
    return s
  }

  advance(key, tick) {
    const s = this.#state(key)
    if (s.lastTick === null) {
      s.lastTick = tick
      return
    }
    if (tick > s.lastTick) {
      const delta = tick - s.lastTick
      s.tokensNum += this.refill * delta
      if (s.tokensNum > this.capNum) s.tokensNum = this.capNum
      s.lastTick = tick
    }
  }

  allow(key) {
    const s = this.#state(key)
    return s.tokensNum >= this.per
  }

  record(key) {
    const s = this.#state(key)
    s.tokensNum -= this.per
  }
}

export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  #state(key) {
    let s = this.states.get(key)
    if (!s) {
      s = []
      this.states.set(key, s)
    }
    return s
  }

  advance(key, tick) {
    const s = this.#state(key)
    const threshold = tick - this.span
    let i = 0
    while (i < s.length && s[i] <= threshold) i++
    if (i > 0) s.splice(0, i)
  }

  allow(key) {
    return BigInt(this.#state(key).length) < this.limit
  }

  record(key, tick) {
    this.#state(key).push(tick)
  }
}
"}

