{"file_path":"src/simulate.js","content":"import { LineError } from './errors.js'
import { TokenBucket, SlidingWindow } from './policies.js'

const NAME_RE = /^[A-Za-z0-9_.\/:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

function checkInt(value, field, least, line) {
  if (!INT_RE.test(value) || BigInt(value) < least) {
    throw new LineError(line, `${field} must be an integer of at least ${least}`)
  }
  return BigInt(value)
}

function checkName(value, kind, line) {
  if (!NAME_RE.test(value)) {
    throw new LineError(line, `invalid ${kind} ${value}`)
  }
  return value
}

/**
 * Parses and simulates the limiter file, returning the requested output.
 *
 * mode is 'replay' or 'summary'.
 */
export function simulate(text, mode) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()

  const policies = new Map() // name -> policy instance
  const routes = [] // { prefix, policyNames: [...] } in declaration order
  let seenEvent = false
  let lastTick = null

  const events = [] // { tick, key, allow, deniedBy }
  const totals = new Map() // key -> { allowed, denied }
  let totalAllowed = 0n
  let totalDenied = 0n

  const replayLines = mode === 'replay' ? [] : null

  for (let i = 0; i < rawLines.length; i++) {
    const lineNo = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (seenEvent) {
        throw new LineError(lineNo, 'declarations must come before the first event')
      }
    }

    if (directive === 'bucket') {
      if (tokens.length !== 5) {
        throw new LineError(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      }
      const [, name, capacityStr, refillStr, perStr] = tokens
      checkName(name, 'policy name', lineNo)
      const capacity = checkInt(capacityStr, 'capacity', 1n, lineNo)
      const refill = checkInt(refillStr, 'refill', 0n, lineNo)
      const per = checkInt(perStr, 'per', 1n, lineNo)
      if (policies.has(name)) {
        throw new LineError(lineNo, `policy ${name} is declared twice`)
      }
      policies.set(name, new TokenBucket(capacity, refill, per))
    } else if (directive === 'window') {
      if (tokens.length !== 4) {
        throw new LineError(lineNo, 'expected window <name> <limit> <span>')
      }
      const [, name, limitStr, spanStr] = tokens
      checkName(name, 'policy name', lineNo)
      const limit = checkInt(limitStr, 'limit', 0n, lineNo)
      const span = checkInt(spanStr, 'span', 1n, lineNo)
      if (policies.has(name)) {
        throw new LineError(lineNo, `policy ${name} is declared twice`)
      }
      policies.set(name, new SlidingWindow(limit, span))
    } else if (directive === 'route') {
      if (tokens.length < 3) {
        throw new LineError(lineNo, 'expected route <prefix> <policy>...')
      }
      const prefix = tokens[1]
      const policyNames = tokens.slice(2)
      checkName(prefix, 'route prefix', lineNo)
      for (const name of policyNames) {
        if (!policies.has(name)) {
          throw new LineError(lineNo, `unknown policy ${name}`)
        }
      }
      if (routes.some((r) => r.prefix === prefix)) {
        throw new LineError(lineNo, `prefix ${prefix} is routed twice`)
      }
      routes.push({ prefix, policyNames })
    } else if (directive === 'event') {
      if (tokens.length !== 3) {
        throw new LineError(lineNo, 'expected event <tick> <key>')
      }
      const [, tickStr, key] = tokens
      const tick = checkInt(tickStr, 'tick', 0n, lineNo)
      checkName(key, 'key', lineNo)
      if (lastTick !== null && tick < lastTick) {
        throw new LineError(lineNo, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      seenEvent = true

      // Find the longest matching route prefix.
      let best = null
      for (const r of routes) {
        if (key.startsWith(r.prefix)) {
          if (best === null || r.prefix.length > best.prefix.length) best = r
        }
      }

      let allowed = true
      let deniedBy = null
      if (best !== null) {
        const routePolicies = best.policyNames.map((n) => ({ name: n, policy: policies.get(n) }))
        for (const { policy } of routePolicies) policy.advance(key, tick)
        for (const { name, policy } of routePolicies) {
          if (!policy.allow(key)) {
            allowed = false
            deniedBy = name
            break
          }
        }
        if (allowed) {
          for (const { policy } of routePolicies) policy.record(key, tick)
        }
      }

      let t = totals.get(key)
      if (!t) {
        t = { allowed: 0n, denied: 0n }
        totals.set(key, t)
      }
      if (allowed) {
        t.allowed++
        totalAllowed++
      } else {
        t.denied++
        totalDenied++
      }

      if (replayLines) {
        replayLines.push(allowed ? `${tick} ${key} allow` : `${tick} ${key} deny ${deniedBy}`)
      }
    } else {
      throw new LineError(lineNo, `unknown directive ${directive}`)
    }
  }

  if (mode === 'replay') {
    return replayLines.length ? replayLines.join('\n') + '\n' : ''
  }

  const keys = Array.from(totals.keys()).sort()
  const lines = keys.map((k) => {
    const t = totals.get(k)
    return `${k} allowed=${t.allowed} denied=${t.denied}`
  })
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
  return lines.join('\n') + '\n'
}
"}

