    if (trimmed === '' || trimmed.startsWith('#')) continue
    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (seenEvent) {
        throw new LineError(lineNo, 'declarations must come before the first event')
      }
    }

    if (directive === 'bucket') {
      if (tokens.length !== 5) {
        throw new LineError(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      }
      const [, name, capacityStr, refillStr, perStr] = tokens
      checkName(name, 'policy name', lineNo)
      const capacity = checkInt(capacityStr, 'capacity', 1n, lineNo)
      const refill = checkInt(refillStr, 'refill', 0n, lineNo)
      const per = checkInt(perStr, 'per', 1n, lineNo)
      if (policies.has(name)) {
        throw new LineError(lineNo, `policy ${name} is declared twice`)
      }
      policies.set(name, new TokenBucket(capacity, refill, per))
    } else if (directive === 'window') {
      if (tokens.length !== 4) {
        throw new LineError(lineNo, 'expected window <name> <limit> <span>')
      }
      const [, name, limitStr, spanStr] = tokens
      checkName(name, 'policy name', lineNo)
      const limit = checkInt(limitStr, 'limit', 0n, lineNo)
      const span = checkInt(spanStr, 'span', 1n, lineNo)
      if (policies.has(name)) {
        throw new LineError(lineNo, `policy ${name} is declared twice`)
      }
      policies.set(name, new SlidingWindow(limit, span))
    } else if (directive === 'route') {
      if (tokens.length < 3) {
        throw new LineError(lineNo, 'expected route <prefix> <policy>...')
      }
      const prefix = tokens[1]
