/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { simulate } from './simulate.js'
import { LineError } from './errors.js'

const mode = process.argv[2]

if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

const input = readFileSync(0, 'utf8')

try {
  const output = simulate(input, mode)
  process.stdout.write(output)
  process.exit(0)
} catch (err) {
  if (err instanceof LineError) {
    process.stderr.write(`error: line ${err.line}: ${err.message}\n`)
    process.exit(2)
  }
  throw err
}
"}

